1	import React from 'react';
2	import { describe, test, expect, vi, beforeEach } from 'vitest';
3	import { act, render, screen } from '@testing-library/react';
4	
5	// SFCC-863 — the whole point of this suite: DntNotification (Salesforce's placeholder
6	// consent-tracking modal, real Lorem ipsum body copy, no config flag to disable it) must never
7	// render. Mocked with spies rather than simply left unmocked so a future regression (an
8	// upstream sync re-adding the import/hook-call/JSX this story removed) is actually caught —
9	// an unmocked, unimported dependency would make this suite pass trivially either way.
10	const useDntNotification = vi.fn(() => ({ isOpen: false, onOpen: vi.fn(), onClose: vi.fn() }));
11	const DntNotification = vi.fn((props: unknown) => (
12	  <div data-testid="dnt-notification-placeholder" data-props={JSON.stringify(props)}>
13	    Lorem ipsum
14	  </div>
15	));
16	vi.mock('@salesforce/retail-react-app/app/hooks/use-dnt-notification', () => ({
17	  useDntNotification: () => useDntNotification(),
18	  DntNotification: (props: unknown) => DntNotification(props),
19	}));
20	
21	// Everything below is mocked at the smallest surface needed to render App's tree without
22	// crashing — per testing.md, each dependency's own behaviour is already covered by its own
23	// suite (Header/Footer/DrawerMenu/ListMenu each have their own index.test.tsx; the base SFCC
24	// hooks are Salesforce's own tested code). This suite asserts only App's own contract: that it
25	// no longer wires up DntNotification, and that the sibling AuthModal survived the edit intact.
26	// A stable object reference (not a new literal per call) — matches real react-router-dom's
27	// useLocation, which returns the same identity across re-renders unless the URL actually
28	// changes. Needed for the SFCC-885 suite below: a fresh object every render would make App's
29	// pre-existing "close the drawer on location change" effect (see index.tsx's own comment)
30	// re-fire on every re-render, fighting the breakpoint-close assertions before they can run.
31	const mockLocation = { pathname: '/', search: '' };
32	// SFCC-315 — named (not an inline vi.fn()) so the SFCC-315 suite below can assert the bag icon
33	// never navigates.
34	const historyPushSpy = vi.fn();
35	vi.mock('react-router-dom', () => ({
36	  useHistory: () => ({ push: historyPushSpy }),
37	  useLocation: () => mockLocation,
38	}));
39	// Subpath export — not resolvable under Vitest without an explicit mock (see testing.md's
40	// ZimmIcon gap for the same subpath-resolution shape of problem).
41	vi.mock('@salesforce/commerce-sdk-react/components', () => ({
42	  StorefrontPreview: ({ children }: { children: React.ReactNode }) => <>{children}</>,
43	}));
44	vi.mock('@salesforce/pwa-kit-react-sdk/ssr/universal/utils', () => ({
45	  getAssetUrl: (path: string) => `/mocked/${path}`,
46	  getRouterBasePath: () => '',
47	}));
48	vi.mock('@salesforce/retail-react-app/app/hooks/use-active-data', () => ({
