import { useAddToCartModalContext } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';

// Stands in for the real base AddToCartModal (use-add-to-cart-modal.js:76-77), which
// BonusProductSelectionModalProvider renders unconditionally as its own child
// (bonus-product-modal-provider.js:33) on every page. A real, unmocked render of that base
// `.js`-with-JSX file isn't reachable under this project's Vitest config (a separate,
// pre-existing tooling gap — same class as the documented ZimmIcon-under-Vitest gap in
// testing.md) — this probe reproduces its one load-bearing line instead:
// `const {isOpen, onClose, data} = useAddToCartModalContext()`, with no guard. If
// AddToCartModalProvider is ever removed from _app again, useAddToCartModalContext() resolves
// to undefined here exactly as it would for the real component, and this destructure throws.
const addToCartModalProbeSpy = vi.fn();
const AddToCartModalProbe = () => {
  // No guard here, deliberately — matching the real base component exactly (it's a plain,
  // unchecked destructure too; guarding it would test a different, safer shape than what
  // actually ships). `useAddToCartModalContext` resolves to `any` here (the real base module
  // it's typed against has no TypeScript declarations), so this destructure needs no non-null
  // assertion to compile — but it throws at runtime identically either way if `ctx` is
  // `undefined`, which is the actual behaviour this probe exists to catch.
  const ctx = useAddToCartModalContext();
  const { isOpen } = ctx;
  addToCartModalProbeSpy(isOpen);
  return null;
};
vi.mock('@salesforce/retail-react-app/app/hooks/use-bonus-product-selection-modal', () => ({
  BonusProductSelectionModalProvider: ({ children }: { children: React.ReactNode }) => (
    <>
      {children}
      <AddToCartModalProbe />
    </>

